using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Text;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Models;using UCSPyayStudentRegistration.NrcData;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms {
 public class NrcEntry:UserControl { public new ComboBox Region=new ComboBox();public ComboBox Town=new ComboBox();public ComboBox Type=new ComboBox();public TextBox Serial=new TextBox();public NrcEntry(){Height=32;Width=430;Region.Width=55;Town.Width=105;Type.Width=55;Serial.Width=100;foreach(int r in NrcTownshipData.Regions)Region.Items.Add(r);Type.Items.AddRange(new object[]{"N","E","P","T","Y","S"});Region.DropDownStyle=Town.DropDownStyle=Type.DropDownStyle=ComboBoxStyle.DropDownList;Serial.MaxLength=6;Serial.KeyPress+=delegate(object s,KeyPressEventArgs e){e.Handled=!char.IsControl(e.KeyChar)&&!char.IsDigit(e.KeyChar);};Region.SelectedIndexChanged+=delegate{Town.Items.Clear();int r;if(int.TryParse(Convert.ToString(Region.SelectedItem),out r))Town.Items.AddRange(NrcTownshipData.ForRegion(r));if(Town.Items.Count>0)Town.SelectedIndex=0;};Controls.Add(Region);Town.Left=62;Controls.Add(Town);Type.Left=174;Controls.Add(Type);Serial.Left=236;Controls.Add(Serial);if(Region.Items.Count>0)Region.SelectedIndex=0;Type.SelectedIndex=0;}public bool Valid(){int r;return int.TryParse(Convert.ToString(Region.SelectedItem),out r)&&NrcValidation.IsValid(r,Convert.ToString(Town.SelectedItem),Convert.ToString(Type.SelectedItem),Serial.Text);}public string Value(){return NrcValidation.Format(Convert.ToInt32(Region.SelectedItem),Convert.ToString(Town.SelectedItem),Convert.ToString(Type.SelectedItem),Serial.Text);} }
 public class FrmApplicationWizard:StyledForm {
  WizardData data=new WizardData();int year;TabControl tabs=new TabControl{Dock=DockStyle.Fill};TextBox name=T(),phone=T(),email=T(),address=T(),major=T();ComboBox gender=C();DateTimePicker dob=new DateTimePicker{Width=300};NrcEntry studentNrc=new NrcEntry(),fatherNrc=new NrcEntry(),motherNrc=new NrcEntry();PictureBox profileDocumentPreview=new PictureBox{Width=58,Height=42,SizeMode=PictureBoxSizeMode.Zoom,BorderStyle=BorderStyle.FixedSingle,BackColor=Color.White};PictureBox photo=new PictureBox{Width=150,Height=185,BorderStyle=BorderStyle.FixedSingle,SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.White};string photoPath,nrcFront,nrcBack,fatherNrcFront,fatherNrcBack,motherNrcFront,motherNrcBack,paymentReceipt;TextBox fatherName=T(),fatherPhone=T(),fatherJob=T(),fatherAddress=T(),motherName=T(),motherPhone=T(),motherJob=T(),motherAddress=T();Dictionary<string,string> docs=new Dictionary<string,string>();Dictionary<string,Label> docLabels=new Dictionary<string,Label>();ComboBox method=C();Label accountInfo=new Label{Width=440,Height=105,BorderStyle=BorderStyle.FixedSingle,Padding=new Padding(10),BackColor=Color.White};PictureBox qr=new PictureBox{Width=130,Height=130,SizeMode=PictureBoxSizeMode.Zoom,BorderStyle=BorderStyle.FixedSingle};TextBox paid=T(),transaction=T();DateTimePicker paymentDate=new DateTimePicker{Width=300};CheckBox confirm=new CheckBox{Text="I confirm that all information and documents are correct.",AutoSize=true};
  static TextBox T(){return new TextBox{Width=300};}static ComboBox C(){return new ComboBox{Width=300,DropDownStyle=ComboBoxStyle.DropDownList};}public FrmApplicationWizard(int selectedYear,string proof){year=selectedYear;data.SeatOrRoll=proof;Text="Student Registration";Size=new Size(1000,740);MinimumSize=new Size(900,650);Controls.Add(tabs);Controls.Add(UiTheme.Heading("Student Registration","Complete each section. Fields marked * are required."));StudentPage();ParentPage();AcademicPage();DocumentsPage();PaymentPage();ReviewPage();AddNavigation();}
  void AddNavigation(){var bar=new Panel{Dock=DockStyle.Bottom,Height=62,BackColor=Color.White,Padding=new Padding(18,10,18,10)};var back=UiTheme.Secondary("< Back");back.Width=125;back.Dock=DockStyle.Left;var next=new Button{Text="Next >",Width=125,Dock=DockStyle.Right};var step=new Label{Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.DimGray};bar.Controls.Add(step);bar.Controls.Add(back);bar.Controls.Add(next);Controls.Add(bar);bar.BringToFront();back.Click+=delegate{if(tabs.SelectedIndex>0)tabs.SelectedIndex--;};next.Click+=delegate{if(tabs.SelectedIndex<tabs.TabPages.Count-1)tabs.SelectedIndex++;};tabs.SelectedIndexChanged+=delegate{back.Enabled=tabs.SelectedIndex>0;next.Visible=tabs.SelectedIndex<tabs.TabPages.Count-1;step.Text="Step "+(tabs.SelectedIndex+1)+" of "+tabs.TabPages.Count;};back.Enabled=false;step.Text="Step 1 of "+tabs.TabPages.Count;}
  FlowLayoutPanel Flow(){return new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(26)};}void Field(Control p,string label,Control c){p.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(3,9,3,2),Font=new Font("Segoe UI",9,FontStyle.Bold)});p.Controls.Add(c);}void Page(string title,Control content){var page=new TabPage(title){BackColor=UiTheme.Pale};page.Controls.Add(content);tabs.TabPages.Add(page);}Button Upload(string title,Action<string> selected,bool imageOnly){var b=new Button{Text=title,Width=150,Height=35};b.Click+=delegate{using(var o=new OpenFileDialog{Filter=imageOnly?"Images|*.jpg;*.jpeg;*.png":"Documents|*.jpg;*.jpeg;*.png;*.pdf"})if(o.ShowDialog()==DialogResult.OK){if(!FileHelper.Allowed(o.FileName,!imageOnly)){MessageBox.Show("Only approved file types up to 5 MB are allowed.");return;}selected(FileHelper.CopyUpload(o.FileName,imageOnly?"Photos":"Documents"));}};return b;}Control UploadStatus(string title,Action<string> selected,bool imageOnly,PictureBox preview){var row=new FlowLayoutPanel{Width=430,Height=48,WrapContents=false};var thumb=new PictureBox{Width=48,Height=40,SizeMode=PictureBoxSizeMode.Zoom,BorderStyle=BorderStyle.FixedSingle,BackColor=Color.White,Cursor=Cursors.Hand};var status=new Label{Text="No file selected",Width=190,Height=40,TextAlign=ContentAlignment.MiddleLeft,ForeColor=Color.Maroon,AutoEllipsis=true};string selectedPath="";thumb.Click+=delegate{if(IsImage(selectedPath))ShowImagePreview(selectedPath);};row.Controls.Add(Upload(title,delegate(string path){selectedPath=path;selected(path);status.Text=IsImage(path)?"Photo uploaded":Path.GetFileName(path);status.ForeColor=Color.Green;if(IsImage(path)){try{using(var im=Image.FromFile(path)){thumb.Image=new Bitmap(im);if(preview!=null)preview.Image=new Bitmap(im);}}catch{thumb.Image=null;}}else thumb.Image=null;},imageOnly));row.Controls.Add(thumb);row.Controls.Add(status);return row;}bool IsImage(string path){string ext=Path.GetExtension(path??"").ToLowerInvariant();return File.Exists(path)&&(ext==".jpg"||ext==".jpeg"||ext==".png");}void ShowImagePreview(string path){if(!IsImage(path))return;using(var form=new Form{Text="Image Preview",StartPosition=FormStartPosition.CenterParent,Size=new Size(760,620),BackColor=Color.Black})using(var picture=new PictureBox{Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom}){using(var im=Image.FromFile(path))picture.Image=new Bitmap(im);form.Controls.Add(picture);form.ShowDialog(this);}}
  void StudentPage(){var split=new SplitContainer{Dock=DockStyle.Fill,SplitterDistance=580,FixedPanel=FixedPanel.Panel2};var left=Flow();Field(left,"Student Name *",name);gender.Items.AddRange(new object[]{"Male","Female","Other"});gender.SelectedIndex=0;Field(left,"Gender *",gender);Field(left,"Date of Birth *",dob);Field(left,"NRC (Region / Township / Type / 6 digits) *",studentNrc);Field(left,"Phone *",phone);Field(left,"Email *",email);Field(left,"Address *",address);Field(left,"Major / Specialization *",major);Field(left,"NRC Front *",UploadStatus("Upload NRC Front",delegate(string p){nrcFront=p;},false,null));Field(left,"NRC Back *",UploadStatus("Upload NRC Back",delegate(string p){nrcBack=p;},false,null));split.Panel1.Controls.Add(left);var right=Flow();right.Controls.Add(new Label{Text="PROFILE PHOTO",AutoSize=true,Font=new Font("Segoe UI",11,FontStyle.Bold)});photo.Cursor=Cursors.Hand;photo.Click+=delegate{if(IsImage(photoPath))ShowImagePreview(photoPath);};right.Controls.Add(photo);right.Controls.Add(Upload("Upload Photo",delegate(string p){photoPath=p;UpdateProfileStatus();},true));right.Controls.Add(new Label{Text="JPG, JPEG or PNG\r\nMaximum 5 MB",AutoSize=true,ForeColor=Color.DimGray});split.Panel2.Controls.Add(right);Page("1. Student",split);}
  void ParentPage(){var split=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Padding=new Padding(10)};split.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));split.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));var father=Flow();father.Padding=new Padding(18);father.Controls.Add(new Label{Text="FATHER INFORMATION",AutoSize=true,Font=new Font("Segoe UI",12,FontStyle.Bold),ForeColor=UiTheme.Navy});Field(father,"Father Name *",fatherName);Field(father,"Father NRC *",fatherNrc);Field(father,"Father NRC Front *",UploadStatus("Upload NRC Front",delegate(string path){fatherNrcFront=path;},false,null));Field(father,"Father NRC Back *",UploadStatus("Upload NRC Back",delegate(string path){fatherNrcBack=path;},false,null));Field(father,"Father Phone *",fatherPhone);Field(father,"Father Occupation *",fatherJob);Field(father,"Father Address *",fatherAddress);var mother=Flow();mother.Padding=new Padding(18);mother.Controls.Add(new Label{Text="MOTHER INFORMATION",AutoSize=true,Font=new Font("Segoe UI",12,FontStyle.Bold),ForeColor=UiTheme.Navy});Field(mother,"Mother Name *",motherName);Field(mother,"Mother NRC *",motherNrc);Field(mother,"Mother NRC Front *",UploadStatus("Upload NRC Front",delegate(string path){motherNrcFront=path;},false,null));Field(mother,"Mother NRC Back *",UploadStatus("Upload NRC Back",delegate(string path){motherNrcBack=path;},false,null));Field(mother,"Mother Phone *",motherPhone);Field(mother,"Mother Occupation *",motherJob);Field(mother,"Mother Address *",motherAddress);split.Controls.Add(father,0,0);split.Controls.Add(mother,1,0);Page("2. Parents",split);}
  void AcademicPage(){var p=Flow();p.Controls.Add(new Label{Text=year==1?"FIRST YEAR ADMISSION":"CONTINUING STUDENT",Font=new Font("Segoe UI",13,FontStyle.Bold),AutoSize=true,ForeColor=UiTheme.Navy});p.Controls.Add(new Label{Text="Academic Year: "+Get("AcademicYear","2026-2027")+"\r\nUniversity Year: "+year+"\r\nVerified reference: "+data.SeatOrRoll,AutoSize=true,Font=new Font("Segoe UI",11),Padding=new Padding(0,12,0,0)});p.Controls.Add(new Label{Text=year==1?"The academic year is supplied automatically. No previous-university information is required.":"Your existing roll number is preserved and eligibility is based on the latest semester result.",Width=650,Height=55,ForeColor=Color.DimGray});Page("3. Academic",p);}
  void DocumentsPage(){var p=Flow();p.Controls.Add(new Label{Text="REQUIRED DOCUMENTS",Font=new Font("Segoe UI",13,FontStyle.Bold),AutoSize=true,ForeColor=UiTheme.Navy});var profileRow=new FlowLayoutPanel{Width=820,Height=58,WrapContents=false};profileRow.Controls.Add(new Label{Text="Profile Photo *",Width=300,Height=45,TextAlign=ContentAlignment.MiddleLeft,Font=new Font("Segoe UI",9,FontStyle.Bold)});var profileUpload=Upload("Upload Profile Photo",delegate(string path){photoPath=path;UpdateProfileStatus();},true);profileRow.Controls.Add(profileUpload);profileDocumentPreview.Cursor=Cursors.Hand;profileDocumentPreview.Click+=delegate{if(IsImage(photoPath))ShowImagePreview(photoPath);};profileRow.Controls.Add(profileDocumentPreview);p.Controls.Add(profileRow);string[] required=year==1?new[]{"10th Grade Pass Certificate","10th Grade Mark Sheet","Ward / Village Recommendation Letter","Police Station Recommendation Letter"}:new[]{"Latest Semester Result / Academic Document"};foreach(string type in required){string documentType=type;var row=new FlowLayoutPanel{Width=850,Height=58,WrapContents=false};row.Controls.Add(new Label{Text=documentType+" *",Width=300,Height=45,TextAlign=ContentAlignment.MiddleLeft});row.Controls.Add(UploadStatus("Upload",delegate(string path){docs[documentType]=path;},false,null));p.Controls.Add(row);}var optional="Other Supporting Document (optional)";var optionalRow=new FlowLayoutPanel{Width=850,Height=58,WrapContents=false};optionalRow.Controls.Add(new Label{Text=optional,Width=300,Height=45,TextAlign=ContentAlignment.MiddleLeft});optionalRow.Controls.Add(UploadStatus("Upload",delegate(string path){docs[optional]=path;},false,null));p.Controls.Add(optionalRow);Page("4. Documents",p);}
  void PaymentPage(){var p=Flow();p.Controls.Add(new Label{Text="Registration Fee: "+new SystemSettingsQuery().Fee().ToString("N0")+" MMK",Font=new Font("Segoe UI",14,FontStyle.Bold),AutoSize=true,ForeColor=UiTheme.Navy});method.Items.AddRange(new object[]{"Mobile Payment","Banking"});method.SelectedIndexChanged+=delegate{ShowAccount();};method.SelectedIndex=0;Field(p,"Payment Method *",method);p.Controls.Add(accountInfo);p.Controls.Add(qr);Field(p,"Paid Amount *",paid);Field(p,"Transaction ID *",transaction);Field(p,"Payment Date *",paymentDate);Field(p,"Payment Receipt *",UploadStatus("Upload Receipt",delegate(string path){paymentReceipt=path;},false,null));Page("5. Payment",p);}
  void ShowAccount(){bool mobile=Convert.ToString(method.SelectedItem)=="Mobile Payment";accountInfo.Text=mobile?"KPay\r\nAccount Name: "+Get("KPayAccountName","UCS Pyay Finance (Demo)")+"    Phone: "+Get("KPayPhone","09-000000000")+"\r\n\r\nWave Pay\r\nAccount Name: "+Get("WaveAccountName","UCS Pyay Finance (Demo)")+"    Phone: "+Get("WavePhone","09-000000000"):"Bank: "+Get("BankName","Demo Bank")+"\r\nAccount Name: "+Get("BankAccountName","UCS Pyay Finance (Demo)")+"\r\nAccount Number: "+Get("BankAccountNumber","000-000-000")+"\r\nBranch: "+Get("BankBranch","Pyay Demo Branch");string path=Get("PaymentQRPath","");if(File.Exists(path))using(var im=Image.FromFile(path))qr.Image=new Bitmap(im);}
  void ReviewPage(){var p=Flow();var summary=new Label{Width=760,Height=290,BackColor=Color.White,BorderStyle=BorderStyle.FixedSingle,Padding=new Padding(14)};p.Controls.Add(summary);p.Controls.Add(confirm);var submit=new Button{Text="Submit Registration",Width=220,Height=45};p.Controls.Add(submit);tabs.SelectedIndexChanged+=delegate{if(tabs.SelectedTab!=null&&tabs.SelectedTab.Text.StartsWith("6"))summary.Text=Summary();};submit.Click+=delegate{Submit();};Page("6. Review",p);}
  string Summary(){return "Student: "+name.Text+"\r\nYear: "+year+"     Academic Year: "+Get("AcademicYear","2026-2027")+"\r\nNRC: "+(studentNrc.Valid()?studentNrc.Value():"Incomplete")+"\r\nPhone: "+phone.Text+"     Email: "+email.Text+"\r\nMajor: "+major.Text+"\r\n\r\nFather: "+fatherName.Text+"     Mother: "+motherName.Text+"\r\nUpload checklist:\r\n  Profile Photo: "+Mark(photoPath)+"\r\n  Student NRC Front / Back: "+Mark(nrcFront)+" / "+Mark(nrcBack)+"\r\n  Father NRC Front / Back: "+Mark(fatherNrcFront)+" / "+Mark(fatherNrcBack)+"\r\n  Mother NRC Front / Back: "+Mark(motherNrcFront)+" / "+Mark(motherNrcBack)+"\r\n  Required Documents: "+docs.Count+" uploaded\r\n  Payment Receipt: "+Mark(paymentReceipt)+"\r\nPayment: "+paid.Text+" MMK by "+Convert.ToString(method.SelectedItem)+"\r\nTransaction: "+transaction.Text;}
  void Submit(){try{if(!Required(name.Text,phone.Text,email.Text,address.Text,major.Text,fatherName.Text,fatherPhone.Text,fatherJob.Text,fatherAddress.Text,motherName.Text,motherPhone.Text,motherJob.Text,motherAddress.Text)||!studentNrc.Valid()||!fatherNrc.Valid()||!motherNrc.Valid()){MessageBox.Show("Complete all required personal and parent fields. Every NRC needs exactly six digits.");return;}if(!ValidationHelper.MyanmarPhone(phone.Text)||!ValidationHelper.MyanmarPhone(fatherPhone.Text)||!ValidationHelper.MyanmarPhone(motherPhone.Text)||!ValidationHelper.Email(email.Text)){MessageBox.Show("Check the email and Myanmar phone numbers.");return;}var missing=new List<string>();if(string.IsNullOrEmpty(photoPath))missing.Add("Profile Photo");if(string.IsNullOrEmpty(nrcFront))missing.Add("Student NRC Front");if(string.IsNullOrEmpty(nrcBack))missing.Add("Student NRC Back");if(string.IsNullOrEmpty(fatherNrcFront))missing.Add("Father NRC Front");if(string.IsNullOrEmpty(fatherNrcBack))missing.Add("Father NRC Back");if(string.IsNullOrEmpty(motherNrcFront))missing.Add("Mother NRC Front");if(string.IsNullOrEmpty(motherNrcBack))missing.Add("Mother NRC Back");if(missing.Count>0){MessageBox.Show("Please upload the following missing files:\r\n\r\n• "+string.Join("\r\n• ",missing.ToArray()),"Missing Uploads");return;}int needed=year==1?4:1;if(docs.Count<needed){MessageBox.Show("Upload every required document shown in the checklist.");return;}decimal amount,fee=new SystemSettingsQuery().Fee();if(!decimal.TryParse(paid.Text,out amount)||amount!=fee||string.IsNullOrWhiteSpace(transaction.Text)||string.IsNullOrEmpty(paymentReceipt)){MessageBox.Show("Enter the exact fee, transaction ID, and payment receipt.");return;}if(!confirm.Checked){MessageBox.Show("Confirm the information before submitting.");return;}data.Student.StudentName=name.Text.Trim();data.Student.Gender=Convert.ToString(gender.SelectedItem);data.Student.DateOfBirth=dob.Value.Date;data.Student.Nrc=studentNrc.Value();data.Student.Phone=phone.Text.Trim();data.Student.Email=email.Text.Trim();data.Student.Address=address.Text.Trim();data.Student.Major=major.Text.Trim();data.Student.Year=year;data.Student.AcademicYear=Get("AcademicYear","2026-2027");data.Student.PhotoPath=photoPath;if(year>1)data.Student.UniversityRollNo=data.SeatOrRoll;data.Parent.FatherName=fatherName.Text;data.Parent.FatherNrc=fatherNrc.Value();data.Parent.FatherPhone=fatherPhone.Text;data.Parent.FatherOccupation=fatherJob.Text;data.Parent.FatherAddress=fatherAddress.Text;data.Parent.MotherName=motherName.Text;data.Parent.MotherNrc=motherNrc.Value();data.Parent.MotherPhone=motherPhone.Text;data.Parent.MotherOccupation=motherJob.Text;data.Parent.MotherAddress=motherAddress.Text;AddDoc("Profile Photo",photoPath);AddDoc("Student NRC Front",nrcFront);AddDoc("Student NRC Back",nrcBack);AddDoc("Father NRC Front",fatherNrcFront);AddDoc("Father NRC Back",fatherNrcBack);AddDoc("Mother NRC Front",motherNrcFront);AddDoc("Mother NRC Back",motherNrcBack);foreach(var d in docs)AddDoc(d.Key,d.Value);AddDoc("Payment Receipt",paymentReceipt);data.Payment.RequiredAmount=fee;data.Payment.PaidAmount=amount;data.Payment.Method=Convert.ToString(method.SelectedItem);data.Payment.TransactionId=transaction.Text.Trim();data.Payment.PaymentDate=paymentDate.Value.Date;data.Payment.ReceiptPath=paymentReceipt;string no=new ApplicationQuery().Submit(data);MessageBox.Show("Registration submitted successfully.\r\n\r\nApplication Number: "+no+"\r\nKeep this number to check your status.","Submission Complete");Close();}catch(Exception ex){MessageBox.Show("Submission failed. "+ex.Message,"Submission Error");}}
  void UpdateProfileStatus(){if(string.IsNullOrEmpty(photoPath)||!File.Exists(photoPath)){photo.Image=null;profileDocumentPreview.Image=null;return;}try{using(var im=Image.FromFile(photoPath)){photo.Image=new Bitmap(im);profileDocumentPreview.Image=new Bitmap(im);}}catch{photo.Image=null;profileDocumentPreview.Image=null;}}string Mark(string path){return string.IsNullOrEmpty(path)?"MISSING":"Uploaded";}void AddDoc(string type,string path){data.Documents.Add(new RegistrationDocument{DocumentType=type,FileName=Path.GetFileName(path),FilePath=path,FileSize=new FileInfo(path).Length});}bool Required(params string[] values){foreach(string v in values)if(string.IsNullOrWhiteSpace(v))return false;return true;}string Get(string key,string fallback){try{string v=new SystemSettingsQuery().Get(key);return string.IsNullOrWhiteSpace(v)?fallback:v;}catch{return fallback;}}
 }
